// Collect dual vertices (weighted points) for each cell
std::vector<Point> const &all_vertices = rt.points();
std::vector<Point> dual_vertices;
dual_vertices.reserve(all_vertices.size());

for (auto const &v : all_vertices) {
    // The dual vertex of a regular triangulation cell is its weighted point's
    // location (the power diagram vertex). CGAL provides it via
    //   v.point().point()
    // where v is a cell handle. However, RT::Cell_handle is not directly
    // iterable; we instead iterate over all finite cells.
    // The regular triangulation provides a range of finite cells via
    //   rt.finite_cells_begin() / rt.finite_cells_end().
    // We'll fill dual_vertices later when processing facets.
    (void)v; // placeholder to avoid unused warning
}

// Map each cell handle to an index in dual_vertices
std::unordered_map<RT::Cell_handle, unsigned> cell_index;
unsigned idx = 0;
for (auto cit = rt.finite_cells_begin(); cit != rt.finite_cells_end(); ++cit) {
    // The dual vertex of a cell is the circumcenter of its weighted points.
    // CGAL provides it via rt.dual(cit) which returns a Point.
    Point p = rt.dual(cit);
    dual_vertices.push_back(p);
    cell_index[cit] = idx++;
}

// Prepare the mesh to store edges
Mesh<Point, double> mesh;
mesh.vertices = std::move(dual_vertices);

// Iterate over all facets (triangular faces of the 3‑D regular triangulation)
// Each facet corresponds to an edge of the 2‑D power diagram.
for (auto fit = rt.finite_facets_begin(); fit != rt.finite_facets_end(); ++fit) {
    RT::Facet const &facet = *fit;
    // A facet is a pair (cell, index) where index is the vertex opposite
    // the facet in the cell. The dual edge connects the two cells that share
    // this facet.
    RT::Cell_handle c1 = facet.first;
    unsigned       i  = facet.second;

    // The neighboring cell across the facet
    RT::Cell_handle c2 = c1->neighbor(i);
    if (rt.is_infinite(c2) || rt.is_infinite(c1))
        continue; // ignore facets incident to the infinite cell

    // Apply the facet size threshold: keep only “large” facets.
    if (!is_large_facet(rt, facet, threshold))
        continue;

    // Retrieve indices of the dual vertices for the two cells.
    unsigned v1 = cell_index.at(c1);
    unsigned v2 = cell_index.at(c2);

    // Store the edge as a segment (pair of vertex indices) with dummy info.
    // The info field for edges is not used elsewhere; we store 0.0.
    mesh.push_back({v1, v2}, 0.0);
}

// Return the constructed mesh containing power‑diagram edges.
return mesh;
